    """True if word ends a sentence per the spec."""
    if word in _ABBREVIATIONS:
        return False
    # Strip trailing closing quotes/brackets to inspect the terminator run.
    stripped = word.rstrip('"\'\)\]')
    if not stripped or stripped[-1] not in _TERMINATORS:
        return False
    # Check if the word ends with a run of terminators (not that the entire word is terminators).
    # Find the trailing run of terminators.
    i = len(stripped) - 1
    while i >= 0 and stripped[i] in _TERMINATORS:
        i -= 1
    # If we moved left from the end, there's a trailing terminator run.
    return i < len(stripped) - 1"
